// Des: Tests for nt-vend-zenr: request shape, REQS002, credits
// Flo: fake transport captures request > canned replies > assert Rsp
// I/O: canned bodies > pass or fail
// Run: zig build test
// ===================================================================
const std = @import("std"); const base = @import("nt-vend-base.zig"); const zenr = @import("nt-vend-zenr.zig");
const Fake = struct { seen: ?base.Http = null, code: u16, body: []const u8, pub fn send(self: *Fake) base.Send { return .{ .ctx2 = self, .call = cal2 }; } fn cal2(ctx2: *anyopaque, gpaz: std.mem.Allocator, _: std.Io, http: base.Http) anyerror!base.Back { const self: *Fake = @ptrCast(@alignCast(ctx2)); self.seen = http; return .{ .code = self.code, .body = try gpaz.dupe(u8, self.body) }; } };
test "plain, render and premium build the documented URLs" { var aren = std.heap.ArenaAllocator.init(std.testing.allocator); defer aren.deinit(); const allo = aren.allocator(); const one2 = try zenr.requBuil(allo, "K1", .{ .urlz = "https://a.com/x?y=1", .mode = .plain }); try std.testing.expect(!one2.post); try std.testing.expectEqualStrings("https://api.zenrows.com/v1/?apikey=K1&url=https%3A%2F%2Fa.com%2Fx%3Fy%3D1", one2.urlz); const two2 = try zenr.requBuil(allo, "K1", .{ .urlz = "https://a.com/", .mode = .rend }); try std.testing.expect(std.mem.endsWith(u8, two2.urlz, "&js_render=true")); const triz = try zenr.requBuil(allo, "K1", .{ .urlz = "https://a.com/", .mode = .prem }); try std.testing.expect(std.mem.endsWith(u8, triz.urlz, "&js_render=true&premium_proxy=true")); }
test "good page: target status passes, credits by mode" { var aren = std.heap.ArenaAllocator.init(std.testing.allocator); defer aren.deinit(); var fakz: Fake = .{ .code = 200, .body = "<html>ok</html>" }; const res4 = try zenr.call(aren.allocator(), std.testing.allocator, std.testing.io, fakz.send(), "K1", .{ .urlz = "https://a.com/", .mode = .rend }); try std.testing.expectEqual(@as(u16, 200), res4.code); try std.testing.expectEqual(@as(u32, 5), res4.cred); try std.testing.expectEqualStrings("<html>ok</html>", res4.body); }
test "REQS002 is a vendor error, uncharged, key never leaks" { var aren = std.heap.ArenaAllocator.init(std.testing.allocator); defer aren.deinit(); var fakz: Fake = .{ .code = 400, .body = "{\"code\":\"REQS002\",\"title\":\"needs js_render\",\"detail\":\"retry\"}" }; const res4 = try zenr.call(aren.allocator(), std.testing.allocator, std.testing.io, fakz.send(), "K1", .{ .urlz = "https://a.com/", .mode = .plain }); try std.testing.expectEqualStrings("REQS002", res4.errz); try std.testing.expectEqual(@as(u32, 0), res4.cred); try std.testing.expectEqual(@as(usize, 0), res4.body.len); }
test "target 403 is not charged; target JSON with a code field is not a vendor error" { var aren = std.heap.ArenaAllocator.init(std.testing.allocator); defer aren.deinit(); var blkz: Fake = .{ .code = 403, .body = "<html>denied</html>" }; const one2 = try zenr.call(aren.allocator(), std.testing.allocator, std.testing.io, blkz.send(), "K1", .{ .urlz = "https://a.com/", .mode = .plain }); try std.testing.expectEqual(@as(u32, 0), one2.cred); try std.testing.expectEqual(@as(u16, 403), one2.code); var jsn2: Fake = .{ .code = 200, .body = "{\"code\":\"ABC123\",\"items\":[1]}" }; const two2 = try zenr.call(aren.allocator(), std.testing.allocator, std.testing.io, jsn2.send(), "K1", .{ .urlz = "https://a.com/", .mode = .plain }); try std.testing.expectEqualStrings("", two2.errz); try std.testing.expectEqual(@as(u32, 1), two2.cred); }
